// Quick lookup: "a|b" (both directions). Order-independent by design — a pair is written once and
// read from either side, so every `why` is phrased about the RELATIONSHIP rather than from one
// side's point of view. Kept as a Map rather than a linear find: the grid resolves 380 pairs on
// every render, and at 190 entries a scan would turn that into ~72k comparisons per pass.
const index = new Map<string, AuthoredRelation>()
for (const r of AUTHORED_RELATIONS) {
  index.set(`${r.pair[0]}|${r.pair[1]}`, r)
  index.set(`${r.pair[1]}|${r.pair[0]}`, r)
}
export const authoredRelation = (a: string, b: string): AuthoredRelation | undefined => index.get(`${a}|${b}`)
